import os, glob, importlib.util, subprocess, sys
s='[C][C][C][Branch1][C][C][C][C][Branch1][C][C][N][Ring1][Ring2][C]'
print('Input:', s)
for m in ['selfies','rdkit','ase','psi4','pyscf','openbabel']:
    print(m, bool(importlib.util.find_spec(m)))
print('Candidate files:')
for p in glob.glob('/home/data4/xiangyu/BioDSA/workdir/**/*', recursive=True)[:100]:
    if os.path.isfile(p): print(p)
try:
    import selfies
    smi=selfies.decoder(s)
    print('Decoded SMILES:', smi)
except Exception as e: print('SELFIES decode error:',repr(e))
try:
    from rdkit import Chem
    mol=Chem.MolFromSmiles(smi)
    print('Canonical SMILES:',Chem.MolToSmiles(mol) if mol else None)
    print('Formula:',Chem.rdMolDescriptors.CalcMolFormula(mol) if mol else None)
except Exception as e: print('RDKit error:',repr(e))
